#[path = "solution.rs"]
mod solution;

use solution::{evaluate, EvalError};

#[test]
fn evaluates_literals_whitespace_and_precedence() {
    assert_eq!(evaluate("42"), Ok(42));
    assert_eq!(evaluate(" \t 2 + 3 * 4 - 8 / 2 \n"), Ok(10));
    assert_eq!(evaluate("20 / 3 * 2"), Ok(12));
    assert_eq!(evaluate("10 - 3 - 2"), Ok(5));
}

#[test]
fn parentheses_and_chained_unary_operators_work() {
    assert_eq!(evaluate("(2 + 3) * 4"), Ok(20));
    assert_eq!(evaluate("---5"), Ok(-5));
    assert_eq!(evaluate("-+-+5"), Ok(5));
    assert_eq!(evaluate("2 * -(3 + 4)"), Ok(-14));
    assert_eq!(evaluate("-9223372036854775807 - 1"), Ok(i64::MIN));
}

#[test]
fn division_truncates_toward_zero() {
    assert_eq!(evaluate("7 / -3"), Ok(-2));
    assert_eq!(evaluate("-7 / 3"), Ok(-2));
    assert_eq!(evaluate("-7 / -3"), Ok(2));
}

#[test]
fn reports_empty_expression() {
    assert_eq!(evaluate(""), Err(EvalError::EmptyExpression));
    assert_eq!(evaluate(" \t\r\n "), Err(EvalError::EmptyExpression));
}

#[test]
fn reports_unexpected_tokens_at_byte_offsets() {
    assert_eq!(evaluate("1 & 2"), Err(EvalError::UnexpectedToken(2)));
    assert_eq!(evaluate("1 2"), Err(EvalError::UnexpectedToken(2)));
    assert_eq!(evaluate("()"), Err(EvalError::UnexpectedToken(1)));
    assert_eq!(evaluate("1)"), Err(EvalError::UnexpectedToken(1)));
    assert_eq!(evaluate("1 +"), Err(EvalError::UnexpectedToken(3)));
    assert_eq!(evaluate("*2"), Err(EvalError::UnexpectedToken(0)));
    assert_eq!(evaluate("1 + é"), Err(EvalError::UnexpectedToken(4)));
}

#[test]
fn reports_missing_closing_parentheses() {
    assert_eq!(evaluate("("), Err(EvalError::MissingClosingParen));
    assert_eq!(evaluate("(1 + 2"), Err(EvalError::MissingClosingParen));
    assert_eq!(evaluate("((1 + 2)"), Err(EvalError::MissingClosingParen));
}

#[test]
fn reports_division_by_zero() {
    assert_eq!(evaluate("10 / 0"), Err(EvalError::DivisionByZero));
    assert_eq!(evaluate("10 / (3 - 3)"), Err(EvalError::DivisionByZero));
}

#[test]
fn detects_literal_and_arithmetic_overflow() {
    assert_eq!(evaluate("9223372036854775808"), Err(EvalError::Overflow));
    assert_eq!(evaluate("999999999999999999999999999999999999"), Err(EvalError::Overflow));
    assert_eq!(evaluate("9223372036854775807 + 1"), Err(EvalError::Overflow));
    assert_eq!(evaluate("-9223372036854775807 - 2"), Err(EvalError::Overflow));
    assert_eq!(evaluate("3037000500 * 3037000500"), Err(EvalError::Overflow));
    assert_eq!(evaluate("(-9223372036854775807 - 1) / -1"), Err(EvalError::Overflow));
    assert_eq!(evaluate("-(-9223372036854775807 - 1)"), Err(EvalError::Overflow));
}

#[test]
fn evaluation_is_repeatable_and_does_not_mutate_input() {
    let source = String::from(" (12 + 6) / 3 ");
    let before = source.clone();
    assert_eq!(evaluate(&source), Ok(6));
    assert_eq!(evaluate(&source), Ok(6));
    assert_eq!(source, before);
}

